import org.openqa.selenium.By;
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.chrome.ChromeDriver;
import org.junit.Test;

public class FGMasterTest {
    @Test
    public void testFGMasterCreate() {
        WebDriver driver = new ChromeDriver();
        driver.get("https://gc-dev.centralindia.cloudapp.azure.com/ambica/auth/login");
        driver.findElement(By.xpath("//button[contains(text(),'Master Data')]")).click();
        driver.findElement(By.xpath("//a[contains(text(),'FG Master')]")).click();
        driver.findElement(By.xpath("//button[contains(text(),'Add New')]")).click();
        driver.findElement(By.cssSelector("input[placeholder='Enter FG item code']")).sendKeys("FG-SEL-01");
        driver.findElement(By.cssSelector("input[placeholder='Enter FG item name']")).sendKeys("Selenium Item");
        driver.findElement(By.xpath("//button[contains(text(),'Save')]")).click();
        driver.quit();
    }
}
